"""Independent history fixtures; mutations remove necessary evidence or violate behavior."""
import copy
import json
import unittest
from pathlib import Path
from verification import linearizability as checker
from verification.async_contract import step

ROOT = Path(__file__).resolve().parents[1]
SPEC = json.loads((ROOT / 'contract/specification.json').read_text())


def fixture(workload=None, order=None, overlap=True):
    """Test-only recorded observations generated by the pure contract, never native code."""
    if workload is None:
        workload = json.loads((ROOT / 'verification/managed-workload.json').read_text())
    histories = []
    for scenario in workload['scenarios']:
        states = {o['id']: {'state': 'Unauthenticated', 'pendingRequestId': None, 'nextRequestId': o['nextRequestId']} for o in scenario['owners']}
        tokens, rows, clock = {}, [], 0
        operations = scenario['operations']
        if order is not None: operations = [next(o for o in operations if o['id'] == ident) for ident in order]
        for phase in sorted({o['phase'] for o in operations}):
            phase_ops = [o for o in operations if o['phase'] == phase]
            invokes = {}
            if overlap:
                for o in phase_ops:
                    clock += 1; invokes[o['id']] = clock
            for o in phase_ops:
                row = copy.deepcopy(o); owner = o['owner']; state = states[owner]
                if not overlap:
                    clock += 1; invokes[o['id']] = clock
                if o['kind'] == 'snapshot':
                    result = {**state, 'effects': [], 'rejection': None}
                else:
                    event = o['event']; name = event['event']
                    if 'tokenRef' in event:
                        ref = event['tokenRef']; token = tokens[(ref['operationId'], ref['effectIndex'])]
                        row['event']['token'] = copy.deepcopy(token)
                        if token['owner'] != owner:
                            result = {**state, 'effects': [], 'rejection': 'ForeignRequest'}
                        else:
                            result = step(SPEC, state['state'], state['pendingRequestId'], state['nextRequestId'], {'event': name, 'requestId': token['requestId']})
                    else:
                        result = step(SPEC, state['state'], state['pendingRequestId'], state['nextRequestId'], event)
                states[owner] = {k: result[k] for k in ('state', 'pendingRequestId', 'nextRequestId')}
                effects = []
                for index, effect in enumerate(result['effects']):
                    if effect['effect'] == 'RequestTokenRefresh':
                        token = {'owner': owner, 'requestId': effect['requestId']}
                        effects.append({'effect': 'RequestTokenRefresh', 'token': token})
                        tokens[(o['id'], index)] = token
                    else: effects.append(effect)
                clock += 1
                row.update(invoke=invokes[o['id']], **{'return': clock}, result={'snapshot': states[owner].copy(), 'effects': effects, 'rejection': result['rejection']})
                rows.append(row)
        histories.append({'scenario': scenario['id'], 'seed': scenario['seed'], 'trial': 0, 'owners': copy.deepcopy(scenario['owners']), 'operations': rows})
    return workload, {'version': 1, 'histories': histories}


class HistoryChecks(unittest.TestCase):
    def setUp(self): self.workload, self.history = fixture()
    def check(self, **kw): return checker.check_document(self.workload, self.history, SPEC, **kw)
    def first(self): return self.history['histories'][0]['operations']
    def test_complete_frozen_scenarios_have_witnesses(self):
        self.assertEqual(self.check()['verdict'], 'PASS')
    def test_impossible_snapshot_is_semantic_fail(self):
        self.first()[0]['result']['snapshot']['nextRequestId'] = 3
        self.assertEqual(self.check()['verdict'], 'FAIL')
    def test_whole_operation_deletion_is_invalid(self):
        self.first().pop()
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_duplicate_operation_is_invalid(self):
        self.first().append(copy.deepcopy(self.first()[0]))
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_missing_snapshot_is_invalid(self):
        self.first()[:] = [o for o in self.first() if o['kind'] != 'snapshot']
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_future_token_is_invalid(self):
        response, producer = self.first()[4], self.first()[3]
        response['invoke'], producer['return'] = producer['return'], response['invoke']
        result = self.check()
        self.assertEqual(result['verdict'], 'INVALID_HISTORY')
        self.assertIn('future/unreturned token producer', result['reason'])
    def test_missing_producer_is_invalid(self):
        self.first()[4]['event']['tokenRef']['operationId'] = 'missing'
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_token_owner_or_number_disagreement_is_invalid(self):
        for key, value in [('owner','A'), ('requestId',2)]:
            with self.subTest(key=key):
                _, self.history = fixture(); self.first()[4]['event']['token'][key] = value
                self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_equal_timestamps_are_invalid(self):
        self.first()[1]['invoke'] = self.first()[0]['invoke']
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_reversed_interval_is_invalid(self):
        row = self.first()[0]; row['return'] = row['invoke'] - 1
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_foreign_owner_acceptance_is_semantic_fail(self):
        row = self.first()[4]; row['result'] = {'snapshot': {'state':'Authenticated','pendingRequestId':None,'nextRequestId':2},'effects':[],'rejection':None}
        self.assertEqual(self.check()['verdict'], 'FAIL')
    def test_node_budget_is_inconclusive(self):
        self.assertEqual(self.check(max_nodes=0)['verdict'], 'INCONCLUSIVE')
    def test_time_budget_is_inconclusive(self):
        self.assertEqual(self.check(max_seconds=0)['verdict'], 'INCONCLUSIVE')
    def test_no_overlap_is_inconclusive(self):
        self.workload, self.history = fixture(overlap=False)
        self.assertEqual(self.check()['verdict'], 'INCONCLUSIVE')
    def test_legal_overlap_can_reorder(self):
        source = copy.deepcopy(self.workload['scenarios'][1])
        # This control tests a specific six-call reorder, with a matching declared inventory.
        source['operations'] = [o for o in source['operations'] if o['id'] in {'login','issue','logout','response','during','final'}]
        w = {'version':1,'scenarios':[source]}
        self.workload, self.history = fixture(w, ['login','issue','response','during','logout','final'])
        self.assertEqual(self.check()['verdict'], 'PASS')
        self.assertIn('response', self.check()['histories'][0]['witness'])
    def test_real_time_forbids_required_reorder(self):
        source = copy.deepcopy(self.workload['scenarios'][1])
        # This control tests a specific six-call reorder, with a matching declared inventory.
        source['operations'] = [o for o in source['operations'] if o['id'] in {'login','issue','logout','response','during','final'}]
        self.workload, self.history = fixture({'version':1,'scenarios':[source]}, ['login','issue','response','during','logout','final'])
        rows = {o['id']:o for o in self.history['histories'][0]['operations']}
        rows['logout']['invoke'], rows['logout']['return'] = 5, 6
        rows['response']['invoke'], rows['response']['return'] = 7, 8
        rows['during']['invoke'], rows['during']['return'] = 9, 10
        self.assertEqual(self.check()['verdict'], 'FAIL')
    def test_cross_owner_real_time_is_preserved(self):
        result = self.check(); self.assertEqual(result['verdict'], 'PASS')
        witness = result['histories'][0]['witness']
        self.assertLess(witness.index('b-issue'), witness.index('foreign-success'))
    def test_unexpected_history_and_input_are_invalid(self):
        self.first()[0]['event']['event'] = 'Logout'
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')
    def test_search_size_bound_is_inconclusive(self):
        self.assertEqual(self.check(max_operations=1)['verdict'], 'INCONCLUSIVE')
    def test_boolean_integer_is_invalid(self):
        self.first()[0]['result']['snapshot']['nextRequestId'] = True
        self.assertEqual(self.check()['verdict'], 'INVALID_HISTORY')

if __name__ == '__main__': unittest.main()
